                "url": "https://bebbopacific.app/sites/somoa/files/styles/content_1200xh_/public/2024-08/20-week-ultrasound.webp?itok=lQwGXHZi",
                "name": "20-week ultrasound.jpg",
                "alt": "20-week ultrasound"
